pub(crate) const HELPER_PATH: &str = "source_built_mantle_native_helper.rs";
pub(crate) fn source_files() -> BTreeMap<String, String> {
    BTreeMap::from([(HELPER_PATH.into(), include_str!("source_built_mantle_programs_native_helper.rs").into())])
}
pub(crate) struct NativeSchedule {
    pub package: String,
    pub phases: Vec<NativeCommandPhase>,
}
fn detector(phases: &mut Vec<NativeCommandPhase>) {
    phases.extend([NativeCommandPhase::Preprocess, NativeCommandPhase::DriverProbe]);
}
fn flag_probe(phases: &mut Vec<NativeCommandPhase>) {
    // is_flag_supported_inner uses an independent Build and family cache.
    detector(phases);
    phases.push(NativeCommandPhase::CapabilityCompile);
}
fn batch(phases: &mut Vec<NativeCommandPhase>, files: &[String]) {
    phases.extend(files.iter().map(|_| NativeCommandPhase::Compile));
    // Original cc::assemble's 4000-byte immutable object-path batch budget.
    let mut remaining = 4000usize;
    let mut occupied = false;
    for file in files {
        let stem = Path::new(file).file_stem().unwrap().to_str().unwrap();
        let length = "/outputs/out-dir/".len() + 16 + 1 + stem.len() + 2;
        if occupied && length > remaining {
            phases.push(NativeCommandPhase::ArchiveCreate);
            remaining = 4000;
        }
        remaining = remaining.saturating_sub(length);
        occupied = true;
    }
    if occupied {
        phases.push(NativeCommandPhase::ArchiveCreate);
    }
    phases.push(NativeCommandPhase::ArchiveIndex);
}
fn names(values: &str) -> Vec<String> {
    values.split_whitespace().map(str::to_owned).collect()
}
const RING_PERLASM: &[(&str, &str)] = &[
    ("crypto/chacha/asm/chacha-x86_64.pl", "chacha-x86_64-elf.S"),
    ("crypto/fipsmodule/aes/asm/aes-gcm-avx2-x86_64.pl", "aes-gcm-avx2-x86_64-elf.S"),
    ("crypto/fipsmodule/aes/asm/aesni-gcm-x86_64.pl", "aesni-gcm-x86_64-elf.S"),
    ("crypto/fipsmodule/aes/asm/aesni-x86_64.pl", "aesni-x86_64-elf.S"),
    ("crypto/fipsmodule/aes/asm/ghash-x86_64.pl", "ghash-x86_64-elf.S"),
    ("crypto/fipsmodule/aes/asm/vpaes-x86_64.pl", "vpaes-x86_64-elf.S"),
    ("crypto/fipsmodule/bn/asm/x86_64-mont.pl", "x86_64-mont-elf.S"),
    ("crypto/fipsmodule/bn/asm/x86_64-mont5.pl", "x86_64-mont5-elf.S"),
    ("crypto/fipsmodule/ec/asm/p256-x86_64-asm.pl", "p256-x86_64-asm-elf.S"),
    ("crypto/fipsmodule/sha/asm/sha512-x86_64.pl", "sha512-x86_64-elf.S"),
    ("crypto/cipher/asm/chacha20_poly1305_x86_64.pl", "chacha20_poly1305_x86_64-elf.S"),
    // Original perlasm_src_dsts appends SHA-256 using the SHA-512 program.
    ("crypto/fipsmodule/sha/asm/sha512-x86_64.pl", "sha256-x86_64-elf.S"),
];
pub(crate) fn selected_schedule(
    package: &str,
    features: &BTreeSet<String>,
    target: &str,
) -> Result<Option<NativeSchedule>, RunError> {
    if !matches!(package, "ring" | "blake3" | "libmimalloc-sys") {
        return Ok(None);
    }
    if !matches!(target, "x86_64-unknown-linux-musl" | "x86_64-unknown-linux-gnu") {
        return Err(error(format!(
            "{package} native schedule requires source-selected x86_64 Linux GNU compiler, not {target}"
        )));
    }
    let mut phases = Vec::new();
    match package {
        "libmimalloc-sys" => {
            detector(&mut phases);
            flag_probe(&mut phases);
            let version = if features.contains("v3") { "v3" } else { "v2" };
            batch(&mut phases, &[format!("c_src/mimalloc/{version}/src/static.c")]);
        }
        "blake3" => {
            detector(&mut phases);
            flag_probe(&mut phases);
            flag_probe(&mut phases);
            if !features.contains("pure") && !features.contains("prefer_intrinsics") {
                detector(&mut phases);
                batch(
                    &mut phases,
                    &names("c/blake3_sse2_x86-64_unix.S c/blake3_sse41_x86-64_unix.S c/blake3_avx2_x86-64_unix.S"),
                );
            }
            if !features.contains("pure") {
                detector(&mut phases);
                batch(
                    &mut phases,
                    &names(if features.contains("prefer_intrinsics") {
                        "c/blake3_avx512.c"
                    } else {
                        "c/blake3_avx512_x86-64_unix.S"
                    }),
                );
            }
        }
        "ring" => {
            detector(&mut phases);
            let mut files = names(
                "crypto/curve25519/curve25519.c crypto/fipsmodule/aes/aes_nohw.c crypto/fipsmodule/bn/montgomery.c crypto/fipsmodule/bn/montgomery_inv.c crypto/fipsmodule/ec/ecp_nistz.c crypto/fipsmodule/ec/gfp_p256.c crypto/fipsmodule/ec/gfp_p384.c crypto/fipsmodule/ec/p256.c crypto/limbs/limbs.c crypto/mem.c crypto/poly1305/poly1305.c crypto/crypto.c crypto/cpu_intel.c crypto/curve25519/curve25519_64_adx.c third_party/fiat/asm/fiat_curve25519_adx_mul.S third_party/fiat/asm/fiat_curve25519_adx_square.S crypto/fipsmodule/ec/p256-nistz.c",
            );
            files.extend(RING_PERLASM.iter().map(|(_, name)| format!("pregenerated/{name}")));
            batch(&mut phases, &files);
            detector(&mut phases);
            batch(&mut phases, &names("crypto/constant_time_test.c"));
        }
        _ => unreachable!(),
    }
    Ok(Some(NativeSchedule {
        package: package.into(),
        phases,
    }))
}
pub(crate) fn script_boundaries(package: &str) -> Vec<ScriptProcessBoundary> {
    if package == "ring" {
        vec![ScriptProcessBoundary {
            receiver: "cmd".into(),
            kind: ScriptProcessKind::Status,
        }]
    } else {
        Vec::new()
    }
}
pub(crate) fn library_overlays(
    package: &str,
    source: &ArtifactRef,
    compiler_path: &str,
) -> Result<Vec<LibraryOverlaySource>, RunError> {
    if package == "cc" {
        super::cc_library_overlays(source, compiler_path)
    } else {
        Ok(Vec::new())
    }
}
/// A separate generator executable shares the original build.rs source and all
/// original functions. Only its entry dispatch is changed; the ordinary script
/// retains the exact original packaged/is_git selection, flags and metadata.
pub(crate) fn generation_overlay(
    package: &str,
    source: &ArtifactRef,
    compiler_path: &str,
) -> Result<Option<LibraryOverlaySource>, RunError> {
    if package != "ring" {
        return Ok(None);
    }
    let source_member = |root: &str| {
        if root.is_empty() {
            "build.rs".to_string()
        } else {
            format!("{}/build.rs", root.trim_end_matches('/'))
        }
    };
    let original = match source {
        ArtifactRef::Source { role, path } => ArtifactRef::Source {
            role: *role,
            path: source_member(path),
        },
        ArtifactRef::ManifestSource {
            role,
            record_identity,
            member,
        } => ArtifactRef::ManifestSource {
            role: *role,
            record_identity: record_identity.clone(),
            member: source_member(member),
        },
        _ => return Err(error("ring generation entry requires exact original build.rs authority")),
    };
    Ok(Some(LibraryOverlaySource {
        original,
        compiler_path: format!("{}/build.rs", compiler_path.trim_end_matches('/')),
        replacements: vec![(
            "None => ring_build_rs_main(&c_root_dir, &core_name_and_version),".into(),
            "None => mantle_generate_sources(&c_root_dir, &core_name_and_version),".into(),
        )],
        append: vec![
            r#"
fn mantle_generate_sources(c_root_dir: &Path, core_name_and_version: &str) {
    let out_dir = PathBuf::from(env::var_os("OUT_DIR").unwrap());
    let arch = env::var("CARGO_CFG_TARGET_ARCH").unwrap();
    let os = env::var("CARGO_CFG_TARGET_OS").unwrap();
    let endian = env::var("CARGO_CFG_TARGET_ENDIAN").unwrap();
    let asm_target = if endian == "little" {
        ASM_TARGETS.iter().find(|target| target.arch == arch && target.oss.contains(&os.as_str()))
    } else { None };
    generate_sources_and_preassemble(&out_dir, asm_target.into_iter(), c_root_dir, core_name_and_version);
}
"#
            .into(),
        ],
    }))
}
fn perlasm(
    program: &mut SourceRecipe,
    tools: &NativeRequestTools,
    id: &str,
    request: ArtifactRef,
    source: &str,
    filename: &str,
    perl: ArtifactRef,
) -> Result<NativeCommandProducts, RunError> {
    let authenticate_id = format!("{id}.authenticate");
    program.steps.push(RecipeStep {
        id: authenticate_id.clone(),
        inputs: BTreeMap::from([
            ("helper".into(), tools.phase_helper.clone()),
            ("request".into(), request),
            ("native-perl".into(), perl.clone()),
            ("package".into(), tools.package.clone()),
        ]),
        outputs: outputs("authenticated", ArtifactKind::Object),
        operation: RecipeOperation::Exec {
            command_state: None,
            merge_stderr: false,
            executable_input: "helper".into(),
            invocation_input: None,
            arguments: vec![
                lit("--ring-request"),
                input("request", ""),
                input("native-perl", ""),
                input("package", source),
                lit(filename),
                output("authenticated"),
            ],
            environment: tools.native.environment.clone(),
            runtime_mounts: tools.native.runtime_mounts.clone(),
            cwd_input: None,
            cwd_output: None,
            output_seeds: BTreeMap::new(),
            stdin_input: None,
            guard: None,
            exit_policy: RecipeExitPolicy::Exact { code: 0 },
        },
    });
    let assembly = append_x86_64_perlasm(
        program,
        id,
        perl,
        product(&program.stage_id, &authenticate_id, "authenticated"),
        tools.package.clone(),
        source,
        filename,
        tools.native.environment.clone(),
        tools.native.runtime_mounts.clone(),
    )?;
    let generate = format!("{id}.generate");
    let translate = format!("{id}.translate");
    let result = format!("{id}.result");
    let mut inputs = BTreeMap::from([
        ("helper".into(), tools.phase_helper.clone()),
        ("assembly".into(), assembly),
    ]);
    let mut arguments = vec![lit("--perlasm-result")];
    for (prefix, step) in [("generate", &generate), ("translate", &translate)] {
        for suffix in ["stdout", "stderr", "exit-status"] {
            let name = format!("{prefix}-{suffix}");
            inputs.insert(name.clone(), product(&program.stage_id, step, suffix));
            arguments.push(input(&name, ""));
        }
    }
    arguments.extend([
        input("assembly", ""),
        lit(filename),
        output("command-stdout"),
        output("command-stderr"),
        output("command-status"),
        output("files"),
    ]);
    let mut result_outputs = outputs("files", ArtifactKind::Tree);
    for name in ["command-stdout", "command-stderr", "command-status"] {
        result_outputs.insert(name.into(), RecipeOutput {
            kind: ArtifactKind::Text,
            bytes_max: super::BYTES_MAX,
        });
    }
    program.steps.push(RecipeStep {
        id: result.clone(),
        inputs,
        outputs: result_outputs,
        operation: RecipeOperation::Exec {
            command_state: None,
            merge_stderr: false,
            executable_input: "helper".into(),
            invocation_input: None,
            arguments,
            environment: tools.native.environment.clone(),
            runtime_mounts: tools.native.runtime_mounts.clone(),
            cwd_input: None,
            cwd_output: None,
            output_seeds: BTreeMap::new(),
            stdin_input: None,
            guard: None,
            exit_policy: RecipeExitPolicy::Exact { code: 0 },
        },
    });
    Ok(NativeCommandProducts {
        stdout: product(&program.stage_id, &result, "command-stdout"),
        stderr: product(&program.stage_id, &result, "command-stderr"),
        status: product(&program.stage_id, &result, "command-status"),
        files: product(&program.stage_id, &result, "files"),
        complete_state: false,
    })
}
pub(crate) fn append_schedule(
    program: &mut SourceRecipe,
    tools: &NativeRequestTools,
    schedule: &NativeSchedule,
    id: &str,
    script: ArtifactRef,
    environment: BTreeMap<String, RecipeWord>,
    extra_inputs: BTreeMap<String, ArtifactRef>,
    runtime_mounts: BTreeMap<String, String>,
) -> Result<ScriptRun, RunError> {
    let mut selected_tools = tools.clone();
    if schedule.package == "ring" {
        let generator = extra_inputs
            .get("ring-generator")
            .ok_or_else(|| error("ring needs original build.rs generator executable"))?
            .clone();
        let perl = extra_inputs
            .get("native-perl")
            .ok_or_else(|| error("ring needs source-produced original Perl executable"))?
            .clone();
        let mut generation_env = environment.clone();
        generation_env.insert("PERL_EXECUTABLE".into(), input("native-perl", ""));
        let generation_id = format!("{id}.sources");
        let generated = append_schedule_with(
            program,
            tools,
            RING_PERLASM,
            &generation_id,
            generator,
            generation_env,
            extra_inputs.clone(),
            runtime_mounts.clone(),
            |program, ordinal, (source, filename), request, _partial| {
                perlasm(
                    program,
                    tools,
                    &format!("{generation_id}.perl-{ordinal}"),
                    request,
                    source,
                    filename,
                    perl.clone(),
                )
            },
        )?;
        let generated_dir = generated.out_dir.clone();
        program.steps.push(generated.step);
        let package_id = format!("{id}.generated-package");
        program.steps.push(RecipeStep {
            id: package_id.clone(),
            inputs: BTreeMap::from([
                ("helper".into(), tools.phase_helper.clone()),
                ("package".into(), tools.package.clone()),
                ("generated".into(), generated_dir),
            ]),
            outputs: outputs("package", ArtifactKind::Tree),
            operation: RecipeOperation::Exec {
                command_state: None,
                merge_stderr: false,
                executable_input: "helper".into(),
                invocation_input: None,
                arguments: vec![
                    lit("--ring-package"),
                    input("package", ""),
                    input("generated", ""),
                    output("package"),
                ],
                environment: tools.native.environment.clone(),
                runtime_mounts: tools.native.runtime_mounts.clone(),
                cwd_input: None,
                cwd_output: None,
                output_seeds: BTreeMap::new(),
                stdin_input: None,
                guard: None,
                exit_policy: RecipeExitPolicy::Exact { code: 0 },
            },
        });
        selected_tools.package = product(&program.stage_id, &package_id, "package");
    }
    append_schedule_with(
        program,
        &selected_tools,
        &schedule.phases,
        id,
        script,
        environment,
        extra_inputs,
        runtime_mounts,
        |program, ordinal, phase, request, partial| {
            append_native_request(program, &selected_tools, *phase, &format!("{id}.native-{ordinal}"), request, partial)
        },
    )
}
